﻿/*
Inference for Llama-2 Transformer model in pure Cuda.
*/

#define _CRT_SECURE_NO_WARNINGS
#include <oneapi/dpl/execution>
#include <oneapi/dpl/algorithm>
#include <sycl/sycl.hpp>
#include <dpct/dpct.hpp>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>
#include <string.h>
#include <time.h>
#include <dpct/dpl_utils.hpp>

// ----------------------------------------------------------------------------
// GPU kernels

void element_wise_add_kernel(sycl::half *dest, sycl::half *src, int size) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int i = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
            item_ct1.get_local_id(2);
    if (i < size)
        dest[i] = (sycl::half)((float)dest[i] + (float)src[i]);
}

void convert_fp32_to_fp16(sycl::half *out, float *in, int elements) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int index = item_ct1.get_group(2) * 256 + item_ct1.get_local_id(2);
    if (index < elements)
        out[index] = (sycl::half)in[index];
}

void convert_fp16_to_fp32(float *out, sycl::half *in, int elements) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int index = item_ct1.get_group(2) * 256 + item_ct1.get_local_id(2);
    if (index < elements)
        out[index] = (float)in[index];
}

// Single block - not enough parallelism for the GPU, but it's just 1% of total time
void rmsnorm_kernel(sycl::half *o, sycl::half *x, sycl::half *weight, int size,
                    int elementsPerThread, float &shared_ss) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    float ss = 0.0f;
    for (int i = 0; i < elementsPerThread; i++) {
        int index = item_ct1.get_local_id(2) + i * 1024;
        if (index < size)
            ss += (float)x[index];
    }

    ss = sycl::reduce_over_group(
        sycl::ext::oneapi::this_work_item::get_work_group<3>(), ss * ss,
        sycl::plus<>());

    if (item_ct1.get_local_id(2) == 0) {
        ss /= size;
        ss += 1e-5f;
        ss = 1.0f / sycl::sqrt(ss);
        shared_ss = ss;
    }
    /*
    DPCT1065:3: Consider replacing sycl::nd_item::barrier() with
    sycl::nd_item::barrier(sycl::access::fence_space::local_space) for better
    performance if there is no access to global memory.
    */
    item_ct1.barrier();
    ss = shared_ss;

    // normalize
    for (int i = 0; i < elementsPerThread; i++) {
        int index = item_ct1.get_local_id(2) + i * 1024;
        if (index < size) {
            float val = (float)x[index];
            val *= ss * (float)weight[index];
            o[index] = (sycl::half)val;
        }
    }
}

// one output per warp so that we can parallelize the dot product across the warp
// Note that ~95% of total time is spent here, so optimizing this is important
void mat_vec_kernel(sycl::half *output, sycl::half *input, sycl::half *weight,
                    int n, int d, int numSerialElements) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int index = item_ct1.get_group(2) * item_ct1.get_local_range(1) +
                item_ct1.get_local_id(1);
    if (index >= d)
        return;

    float sum = 0;
    for (int i = 0; i < numSerialElements; i++) {
        int j = i * 32 + item_ct1.get_local_id(2);
        if (j < n)
            sum += ((float)weight[index * n + j]) * ((float)input[j]);
    }

    sum = sycl::reduce_over_group(

    sum = sycl::reduce_over_group(
        sycl::ext::oneapi::this_work_item::get_sub_group(), sum,
        sycl::plus<>());

    if (item_ct1.get_local_id(2) == 0)
        output[index] = (sycl::half)sum;
}

// Each block processes a single head
void RoPERotation_kernel(sycl::half *sq, sycl::half *sk, sycl::half *f_real,
                         sycl::half *f_imag, int num_heads, int head_size) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int h = item_ct1.get_group(2);
    sycl::half *q = sq + h * head_size;
    sycl::half *k = sk + h * head_size;

    int i = item_ct1.get_local_id(2) * 2;
    float q0 = q[i];
    float q1 = q[i + 1];
    float k0 = k[i];
    float k1 = k[i + 1];
    float fcr = f_real[i / 2];
    float fci = f_imag[i / 2];
    q[i] = q0 * fcr - q1 * fci;
    q[i + 1] = q0 * fci + q1 * fcr;
    k[i] = k0 * fcr - k1 * fci;
    k[i + 1] = k0 * fci + k1 * fcr;
}

void softmax_gpu(float* __restrict__ x, int size, float &shared_val) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();

    int tid = item_ct1.get_local_id(2);
    int step = item_ct1.get_local_range(2);

    // find max value (for numerical stability)
    float max_val = tid < size ? x[tid] : 0;
    for (int i = tid + step; i < size; i += step)
        if (x[i] > max_val)
            max_val = x[i];

    max_val = sycl::reduce_over_group(
        sycl::ext::oneapi::this_work_item::get_work_group<3>(), max_val,
        sycl::maximum<>());
    if (item_ct1.get_local_id(2) == 0)
        shared_val = max_val;
    /*
    DPCT1065:4: Consider replacing sycl::nd_item::barrier() with
    sycl::nd_item::barrier(sycl::access::fence_space::local_space) for better
    performance if there is no access to global memory.
    */
    item_ct1.barrier();
    max_val = shared_val;

    // exp and sum
    float sum = 0.0f;
    for (int i = tid; i < size; i += step) {
        x[i] = sycl::native::exp(x[i] - max_val);
        sum += x[i];
    }

    sum = sycl::reduce_over_group(
        sycl::ext::oneapi::this_work_item::get_work_group<3>(), sum,
        sycl::plus<>());
    if (item_ct1.get_local_id(2) == 0)
        shared_val = sum;
    /*
    DPCT1065:5: Consider replacing sycl::nd_item::barrier() with
    sycl::nd_item::barrier(sycl::access::fence_space::local_space) for better
    performance if there is no access to global memory.
    */
    item_ct1.barrier();
    sum = shared_val;

    // normalize
    for (int i = tid; i < size; i += step)
        x[i] /= sum;
}

// Each block processes a single head
// Poor parallelism and even poorer memory access pattern.
// Ankan - TODO: optimize this.
#define MAX_SEQ_LEN 8192
void MultiHeadAttention_kernel(sycl::half *__restrict__ output,
                               const sycl::half *__restrict__ sq,
                               const sycl::half *__restrict__ key_cache,
                               const sycl::half *__restrict__ value_cache,
                               int num_heads, int head_size, int loff,
                               int seq_len, int dim, float &shared_val,
                               float *att) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int h = item_ct1.get_group(2);

    // get the query vector for this head
    const sycl::half *q = sq + h * head_size;
    // attention scores for this head

    // iterate over all timesteps, including the current one
    for (int t = item_ct1.get_local_id(2); t < seq_len;
         t += item_ct1.get_local_range(2)) {
        // get the key vector for this head and at this timestep
        const sycl::half *k = key_cache + loff + t * dim + h * head_size;
        // calculate the attention score as the dot product of q and k
        float score = 0.0f;
        for (int i = 0; i < head_size; i++)
            score += (float)q[i] * (float)k[i];
        score /= sycl::sqrt((float)head_size);
        // save the score to the attention buffer
        att[t] = score;
    }
    item_ct1.barrier(sycl::access::fence_space::local_space);

    // softmax the scores to get attention weights
    softmax_gpu(att, seq_len, shared_val);
    item_ct1.barrier(sycl::access::fence_space::local_space);

    // weighted sum of the values, store back into xb
    for (int i = item_ct1.get_local_id(2); i < head_size;
         i += item_ct1.get_local_range(2)) {
        float val = 0.0f;
        for (int t = 0; t < seq_len; t++)
            val += att[t] * (float)value_cache[loff + t * dim + h * head_size + i];
        output[h * head_size + i] = (sycl::half)val;
    }
}

void silu_element_wise_mul_kernel(sycl::half *dest, sycl::half *src, int size) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int i = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
            item_ct1.get_local_id(2);
    if (i < size) {
        float val = (float)dest[i];
        val *= 1.0f / (1.0f + sycl::native::exp(-val));
        val *= (float)src[i];
        dest[i] = (sycl::half)val;
    }
}

// ----------------------------------------------------------------------------
// Transformer and RunState structs, and related memory management

typedef struct dpct_type_108837 {
    int dim; // transformer dimension
    int hidden_dim; // for ffn layers
    int n_layers; // number of layers
    int n_heads; // number of query heads
    int n_kv_heads; // number of key/value heads (can be < query heads because of multiquery)
    int vocab_size; // vocabulary size, usually 256 (byte-level)
    int seq_len; // max sequence length
} Config;

typedef struct dpct_type_752777 {
    // token embedding table
    sycl::half *token_embedding_table; // (vocab_size, dim)
    // weights for rmsnorms
    sycl::half *rms_att_weight; // (layer, dim) rmsnorm weights
    sycl::half *rms_ffn_weight; // (layer, dim)
    // weights for matmuls
    sycl::half *wq; // (layer, dim, dim)
    sycl::half *wk; // (layer, dim, dim)
    sycl::half *wv; // (layer, dim, dim)
    sycl::half *wo; // (layer, dim, dim)
    // weights for ffn
    sycl::half *w1; // (layer, hidden_dim, dim)
    sycl::half *w2; // (layer, dim, hidden_dim)
    sycl::half *w3; // (layer, hidden_dim, dim)
    // final rmsnorm
    sycl::half *rms_final_weight; // (dim,)
    // freq_cis for RoPE relatively positional embeddings
    sycl::half *freq_cis_real; // (seq_len, dim/2)
    sycl::half *freq_cis_imag; // (seq_len, dim/2)
    // (optional) classifier weights for the logits, on the last layer
    sycl::half *wcls;
} TransformerWeights;

typedef struct dpct_type_158992 {
    // current wave of activations
    sycl::half *x;   // activation at current time stamp (dim,)
    sycl::half *xb;  // same, but inside a residual branch (dim,)
    sycl::half *xb2; // an additional buffer just for convenience (dim,)
    sycl::half *hb;  // buffer for hidden dimension in the ffn (hidden_dim,)
    sycl::half *hb2; // buffer for hidden dimension in the ffn (hidden_dim,)
    sycl::half *q;   // query (dim,)
    sycl::half *k;   // key (dim,)
    sycl::half *v;   // value (dim,)
    sycl::half *logits_gpu; // output logits
    float* logits_temp; // logits in GPU memory converted to float
    float* logits; // logits copied CPU side
    // kv cache
    sycl::half *key_cache;   // (layer, seq_len, dim)
    sycl::half *value_cache; // (layer, seq_len, dim)
} RunState;

void malloc_run_state(RunState *s, Config *p) {
    dpct::device_ext &dev_ct1 = dpct::get_current_device();
    sycl::queue &q_ct1 = dev_ct1.in_order_queue();
    s->x = sycl::malloc_device<sycl::half>(p->dim, q_ct1);
    s->xb = sycl::malloc_device<sycl::half>(p->dim, q_ct1);
    s->xb2 = sycl::malloc_device<sycl::half>(p->dim, q_ct1);
    s->hb = sycl::malloc_device<sycl::half>(p->hidden_dim, q_ct1);

    s->hb2 = sycl::malloc_device<sycl::half>(p->hidden_dim, q_ct1);
    s->q = sycl::malloc_device<sycl::half>(p->dim, q_ct1);
    s->k = sycl::malloc_device<sycl::half>(p->dim, q_ct1);
    s->v = sycl::malloc_device<sycl::half>(p->dim, q_ct1);
    s->logits_gpu = sycl::malloc_device<sycl::half>(p->vocab_size, q_ct1);
    s->key_cache = sycl::malloc_device<sycl::half>(
        p->n_layers * p->seq_len * p->dim, q_ct1); // potentially huge allocs
    s->value_cache = sycl::malloc_device<sycl::half>(
        p->n_layers * p->seq_len * p->dim, q_ct1);
    s->logits_temp = sycl::malloc_device<float>(p->vocab_size, q_ct1);
    s->logits = (float*)malloc(p->vocab_size * sizeof(float));

    // ensure all mallocs went fine
    if (!s->x || !s->xb || !s->xb2 || !s->hb || !s->hb2 || !s->q
        || !s->k || !s->v || !s->logits || !s->key_cache
        || !s->value_cache || !s->logits_gpu) {
        printf("malloc failed!\n");
        exit(1);
    }
}

void free_run_state(RunState *s) {
    dpct::device_ext &dev_ct1 = dpct::get_current_device();
    sycl::queue &q_ct1 = dev_ct1.in_order_queue();
    dpct::dpct_free(s->x, q_ct1);
    dpct::dpct_free(s->xb, q_ct1);
    dpct::dpct_free(s->xb2, q_ct1);
    dpct::dpct_free(s->hb, q_ct1);
    dpct::dpct_free(s->hb2, q_ct1);
    dpct::dpct_free(s->q, q_ct1);
    dpct::dpct_free(s->k, q_ct1);
    dpct::dpct_free(s->v, q_ct1);
    dpct::dpct_free(s->logits_gpu, q_ct1);
    dpct::dpct_free(s->logits_temp, q_ct1);
    free(s->logits);
    dpct::dpct_free(s->key_cache, q_ct1);
    dpct::dpct_free(s->value_cache, q_ct1);
}

void malloc_weights(TransformerWeights *w, Config *p, int shared_weights) {
    dpct::device_ext &dev_ct1 = dpct::get_current_device();
    sycl::queue &q_ct1 = dev_ct1.in_order_queue();
    w->token_embedding_table =
        sycl::malloc_device<sycl::half>(p->vocab_size * p->dim, q_ct1);
    w->rms_att_weight =
        sycl::malloc_device<sycl::half>(p->n_layers * p->dim, q_ct1);
    w->rms_ffn_weight =
        sycl::malloc_device<sycl::half>(p->n_layers * p->dim, q_ct1);
    w->wq =
        sycl::malloc_device<sycl::half>(p->n_layers * p->dim * p->dim, q_ct1);
    w->wk =
        sycl::malloc_device<sycl::half>(p->n_layers * p->dim * p->dim, q_ct1);
    w->wv =
        sycl::malloc_device<sycl::half>(p->n_layers * p->dim * p->dim, q_ct1);
    w->wo =
        sycl::malloc_device<sycl::half>(p->n_layers * p->dim * p->dim, q_ct1);
    w->w1 = sycl::malloc_device<sycl::half>(
        p->n_layers * p->hidden_dim * p->dim, q_ct1);
    w->w2 = sycl::malloc_device<sycl::half>(
        p->n_layers * p->dim * p->hidden_dim, q_ct1);
    w->w3 = sycl::malloc_device<sycl::half>(
        p->n_layers * p->hidden_dim * p->dim, q_ct1);
    w->rms_final_weight = sycl::malloc_device<sycl::half>(p->dim, q_ct1);
    int head_size = p->dim / p->n_heads;
    w->freq_cis_real =
        sycl::malloc_device<sycl::half>(p->seq_len * head_size / 2, q_ct1);
    w->freq_cis_imag =
        sycl::malloc_device<sycl::half>(p->seq_len * head_size / 2, q_ct1);

    if (shared_weights)
        w->wcls = w->token_embedding_table;
    else
        w->wcls =
            sycl::malloc_device<sycl::half>(p->vocab_size * p->dim, q_ct1);

    // ensure all mallocs went fine
    if (!w->token_embedding_table || !w->rms_att_weight || !w->rms_ffn_weight
        || !w->wq || !w->wk || !w->wv || !w->wo || !w->w1 || !w->w2 || !w->w3 ||
        !w->rms_final_weight || !w->freq_cis_real || !w->freq_cis_imag || !w->wcls) {
        printf("malloc failed!\n");
        exit(1);
    }
}

void free_weights(TransformerWeights *w, int shared_weights) {
    dpct::device_ext &dev_ct1 = dpct::get_current_device();
    sycl::queue &q_ct1 = dev_ct1.in_order_queue();
    dpct::dpct_free(w->token_embedding_table, q_ct1);
    dpct::dpct_free(w->rms_att_weight, q_ct1);
    dpct::dpct_free(w->rms_ffn_weight, q_ct1);
    dpct::dpct_free(w->wq, q_ct1);
    dpct::dpct_free(w->wk, q_ct1);
    dpct::dpct_free(w->wv, q_ct1);
    dpct::dpct_free(w->wo, q_ct1);
    dpct::dpct_free(w->w1, q_ct1);
    dpct::dpct_free(w->w2, q_ct1);
    dpct::dpct_free(w->w3, q_ct1);
    dpct::dpct_free(w->rms_final_weight, q_ct1);
    dpct::dpct_free(w->freq_cis_real, q_ct1);
    dpct::dpct_free(w->freq_cis_imag, q_ct1);
    if (!shared_weights)
        dpct::dpct_free(w->wcls, q_ct1);
}

int divUp(int a, int b) {
    return (a - 1) / b + 1;
}

int uploadWeight(void *w, int elements, FILE *f, void *scratchCpu,
                 void *scratchGpu) {
    dpct::device_ext &dev_ct1 = dpct::get_current_device();
    sycl::queue &q_ct1 = dev_ct1.in_order_queue();
    int count = fread(scratchCpu, sizeof(float), elements, f);
    if (count != elements) return 1;
    // copy and convert fp32->fp16
    /*
    DPCT1124:6: cudaMemcpyAsync is migrated to asynchronous memcpy API. While
    the origin API might be synchronous, it depends on the type of operand
    memory, so you may need to call wait() on event return by memcpy API to
    ensure synchronization behavior.
    */
    q_ct1.memcpy(scratchGpu, scratchCpu, sizeof(float) * elements);
    {
        dpct::has_capability_or_fail(q_ct1.get_device(), {sycl::aspect::fp16});

        q_ct1.parallel_for(
            sycl::nd_range<3>(sycl::range<3>(1, 1, divUp(elements, 256)) *
                                  sycl::range<3>(1, 1, 256),
                              sycl::range<3>(1, 1, 256)),
            [=](sycl::nd_item<3> item_ct1) {
                convert_fp32_to_fp16((sycl::half *)w, (float *)scratchGpu,
                                     elements);
            });
    }
    return 0;
}

// ----------------------------------------------------------------------------
// initialization: read from checkpoint

int checkpoint_init_weights(TransformerWeights *w, Config *p, FILE *f,
                            int shared_weights) {
    dpct::device_ext &dev_ct1 = dpct::get_current_device();
    sycl::queue &q_ct1 = dev_ct1.in_order_queue();
    size_t scratch_size = p->n_layers * std::max(p->dim, p->hidden_dim) * p->dim;
    scratch_size = std::max((size_t)p->vocab_size * p->dim, scratch_size);
    scratch_size *= sizeof(float);
    void* scratchCpu = malloc(scratch_size);
    void* scratchGpu = nullptr;
    scratchGpu = (void *)sycl::malloc_device(scratch_size, q_ct1);
    if (uploadWeight(w->token_embedding_table, p->vocab_size * p->dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->rms_att_weight, p->n_layers * p->dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->wq, p->n_layers * p->dim * p->dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->wk, p->n_layers * p->dim * p->dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->wv, p->n_layers * p->dim * p->dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->wo, p->n_layers * p->dim * p->dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->rms_ffn_weight, p->n_layers * p->dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->w1, p->n_layers * p->dim * p->hidden_dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->w2, p->n_layers * p->hidden_dim * p->dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->w3, p->n_layers * p->dim * p->hidden_dim, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->rms_final_weight, p->dim, f, scratchCpu, scratchGpu)) return 1;

    int head_size = p->dim / p->n_heads;
    if (uploadWeight(w->freq_cis_real, p->seq_len * head_size / 2, f, scratchCpu, scratchGpu)) return 1;
    if (uploadWeight(w->freq_cis_imag, p->seq_len * head_size / 2, f, scratchCpu, scratchGpu)) return 1;

    if (!shared_weights)
        if (uploadWeight(w->wcls, p->vocab_size * p->dim, f, scratchCpu, scratchGpu)) return 1;

    dpct::dpct_free(scratchGpu, q_ct1);
    free(scratchCpu);
    return 0;
}

// ----------------------------------------------------------------------------
// neural net blocks

void accum(sycl::half *a, sycl::half *b, int size) {
    int blocks = divUp(size, 256);
    {
        dpct::has_capability_or_fail(dpct::get_in_order_queue().get_device(),
                                     {sycl::aspect::fp16});

        dpct::get_in_order_queue().parallel_for(
            sycl::nd_range<3>(sycl::range<3>(1, 1, blocks) *
                                  sycl::range<3>(1, 1, 256),
                              sycl::range<3>(1, 1, 256)),
            [=](sycl::nd_item<3> item_ct1) {
                element_wise_add_kernel(a, b, size);
            });
    }
}

void rmsnorm(sycl::half *o, sycl::half *x, sycl::half *weight, int size) {
    int elementsPerThread = divUp(size, 1024);
    /*
    DPCT1049:0: The work-group size passed to the SYCL kernel may exceed the
    limit. To get the device limit, query info::device::max_work_group_size.
    Adjust the work-group size if needed.
    */
    {
        dpct::has_capability_or_fail(dpct::get_in_order_queue().get_device(),
                                     {sycl::aspect::fp16});

        dpct::get_in_order_queue().submit([&](sycl::handler &cgh) {
            sycl::local_accessor<float, 0> shared_ss_acc_ct1(cgh);

            cgh.parallel_for(sycl::nd_range<3>(sycl::range<3>(1, 1, 1024),
                                               sycl::range<3>(1, 1, 1024)),
                             [=](sycl::nd_item<3> item_ct1) {
                                 rmsnorm_kernel(o, x, weight, size,
                                                elementsPerThread,
                                                shared_ss_acc_ct1);
                             });
        });
    }
}

void softmax(float* x, int size) {
    // find max value (for numerical stability)
    float max_val = x[0];
    for (int i = 1; i < size; i++) {
        if (x[i] > max_val) {
            max_val = x[i];
        }
    }
    // exp and sum
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        x[i] = expf(x[i] - max_val);
        sum += x[i];
    }
    // normalize
    for (int i = 0; i < size; i++) {
        x[i] /= sum;
    }
}

void matmul(sycl::half *xout, sycl::half *x, sycl::half *w, int n, int d) {
    int serialElements = divUp(n, 32);
    dpct::dim3 block_dim(32, 4);
    int blocks = divUp(d, 4);
    {
        dpct::has_capability_or_fail(dpct::get_in_order_queue().get_device(),
                                     {sycl::aspect::fp16});

        dpct::get_in_order_queue().parallel_for(
            sycl::nd_range<3>(sycl::range<3>(1, 1, blocks) * block_dim,
                              block_dim),
            [=](sycl::nd_item<3> item_ct1) [[sycl::reqd_sub_group_size(32)]] {

                mat_vec_kernel(xout, x, w, n, d, serialElements);
            });
    }
}

void RoPERotation(sycl::half *q, sycl::half *k, sycl::half *f_real,
                  sycl::half *f_imag, int num_heads, int head_size) {
    /*
    DPCT1049:1: The work-group size passed to the SYCL kernel may exceed the
    limit. To get the device limit, query info::device::max_work_group_size.
    Adjust the work-group size if needed.
    */
    dpct::has_capability_or_fail(dpct::get_in_order_queue().get_device(),
                                 {sycl::aspect::fp16});

    dpct::get_in_order_queue().parallel_for(
        sycl::nd_range<3>(sycl::range<3>(1, 1, num_heads) *
                              sycl::range<3>(1, 1, head_size / 2),
                          sycl::range<3>(1, 1, head_size / 2)),
        [=](sycl::nd_item<3> item_ct1) {
            RoPERotation_kernel(q, k, f_real, f_imag, num_heads, head_size);
        });
}

void MultiHeadAttention(sycl::half *output, sycl::half *q,
                        sycl::half *key_cache, sycl::half *value_cache,
                        int num_heads, int head_size, int loff, int seq_len) {
    int dim = head_size * num_heads;
    /*
    DPCT1049:2: The work-group size passed to the SYCL kernel may exceed the
    limit. To get the device limit, query info::device::max_work_group_size.
    Adjust the work-group size if needed.
    */
    {
        dpct::has_capability_or_fail(dpct::get_in_order_queue().get_device(),
                                     {sycl::aspect::fp16});

        dpct::get_in_order_queue().submit([&](sycl::handler &cgh) {
            sycl::local_accessor<float, 0> shared_val_acc_ct1(cgh);
            /*
            DPCT1101:10: 'MAX_SEQ_LEN' expression was replaced with a value.
            Modify the code to use the original expression, provided in
            comments, if it is correct.
            */
            sycl::local_accessor<float, 1> att_acc_ct1(
                sycl::range<1>(8192 /*MAX_SEQ_LEN*/), cgh);

            cgh.parallel_for(
                sycl::nd_range<3>(sycl::range<3>(1, 1, num_heads) *
                                      sycl::range<3>(1, 1, 1024),
                                  sycl::range<3>(1, 1, 1024)),
                [=](sycl::nd_item<3> item_ct1) {
                    MultiHeadAttention_kernel(
                        output, q, key_cache, value_cache, num_heads, head_size,
                        loff, seq_len, dim, shared_val_acc_ct1,
                        att_acc_ct1.get_multi_ptr<sycl::access::decorated::no>()
                            .get());
                });
        });
    }
}

void siluElementwiseMul(sycl::half *hb, sycl::half *hb2, int size) {
    dpct::has_capability_or_fail(dpct::get_in_order_queue().get_device(),
                                 {sycl::aspect::fp16});

    dpct::get_in_order_queue().parallel_for(
        sycl::nd_range<3>(sycl::range<3>(1, 1, divUp(size, 256)) *
                              sycl::range<3>(1, 1, 256),
                          sycl::range<3>(1, 1, 256)),
        [=](sycl::nd_item<3> item_ct1) {
            silu_element_wise_mul_kernel(hb, hb2, size);
        });
}

void transformer(int token, int pos, Config *p, RunState *s,
                 TransformerWeights *w) {
    dpct::device_ext &dev_ct1 = dpct::get_current_device();
    sycl::queue &q_ct1 = dev_ct1.in_order_queue();

    // a few convenience variables
    sycl::half *x = s->x;
    int dim = p->dim;
    int hidden_dim = p->hidden_dim;
    int head_size = dim / p->n_heads;

    // copy the token embedding into x
    sycl::half *content_row = &(w->token_embedding_table[token * dim]);
    /*
    DPCT1124:7: cudaMemcpyAsync is migrated to asynchronous memcpy API. While
    the origin API might be synchronous, it depends on the type of operand
    memory, so you may need to call wait() on event return by memcpy API to
    ensure synchronization behavior.
    */
    q_ct1.memcpy(x, content_row, dim * sizeof(sycl::half));

    // pluck out the "pos" row of freq_cis_real and freq_cis_imag
    sycl::half *freq_cis_real_row = w->freq_cis_real + pos * head_size / 2;
    sycl::half *freq_cis_imag_row = w->freq_cis_imag + pos * head_size / 2;

    // forward all the layers
    for (int l = 0; l < p->n_layers; l++) {

        // attention rmsnorm
        rmsnorm(s->xb, x, w->rms_att_weight + l * dim, dim);

        // qkv matmuls for this position
        matmul(s->q, s->xb, w->wq + l * dim * dim, dim, dim);
        matmul(s->k, s->xb, w->wk + l * dim * dim, dim, dim);
        matmul(s->v, s->xb, w->wv + l * dim * dim, dim, dim);

        // apply RoPE rotation to the q and k vectors for each head
        RoPERotation(s->q, s->k, freq_cis_real_row, freq_cis_imag_row, p->n_heads, head_size);

        // save key,value at this time step (pos) to our kv cache
        int loff = l * p->seq_len * dim; // kv cache layer offset for convenience
        sycl::half *key_cache_row = s->key_cache + loff + pos * dim;
        sycl::half *value_cache_row = s->value_cache + loff + pos * dim;
        /*
        DPCT1124:8: cudaMemcpyAsync is migrated to asynchronous memcpy API.
        While the origin API might be synchronous, it depends on the type of
        operand memory, so you may need to call wait() on event return by memcpy
        API to ensure synchronization behavior.
        */
        q_ct1.memcpy(key_cache_row, s->k, dim * sizeof(sycl::half));
        /*
        DPCT1124:9: cudaMemcpyAsync is migrated to asynchronous memcpy API.
        While the origin API might be synchronous, it depends on the type of
        operand memory, so you may need to call wait() on event return by memcpy
        API to ensure synchronization behavior.
        */
        q_ct1.memcpy(value_cache_row, s->v, dim * sizeof(sycl::half));

        MultiHeadAttention(s->xb, s->q, s->key_cache, s->value_cache, p->n_heads, head_size, loff, pos+1);

        // final matmul to get the output of the attention
        matmul(s->xb2, s->xb, w->wo + l * dim * dim, dim, dim);

        // residual connection back into x
        accum(x, s->xb2, dim);

        // ffn rmsnorm
        rmsnorm(s->xb, x, w->rms_ffn_weight + l * dim, dim);

        // Now for FFN in PyTorch we have: self.w2(F.silu(self.w1(x)) * self.w3(x))
        // first calculate self.w1(x) and self.w3(x)
        matmul(s->hb, s->xb, w->w1 + l * dim * hidden_dim, dim, hidden_dim);
        matmul(s->hb2, s->xb, w->w3 + l * dim * hidden_dim, dim, hidden_dim);

        // apply F.silu activation on hb and multiply it with hb2
        siluElementwiseMul(s->hb, s->hb2, hidden_dim);

        // final matmul to get the output of the ffn
        matmul(s->xb, s->hb, w->w2 + l * dim * hidden_dim, hidden_dim, dim);

        // residual connection
        accum(x, s->xb, dim);
    }

    // final rmsnorm
    rmsnorm(x, x, w->rms_final_weight, dim);

    // classifier into logits
    matmul(s->logits_gpu, x, w->wcls, p->dim, p->vocab_size);

    // copy logits from GPU->CPU
    {
        dpct::has_capability_or_fail(q_ct1.get_device(), {sycl::aspect::fp16});

        q_ct1.submit([&](sycl::handler &cgh) {
            auto s_logits_temp_ct0 = s->logits_temp;
            auto s_logits_gpu_ct1 = s->logits_gpu;
            auto p_vocab_size_ct2 = p->vocab_size;

            cgh.parallel_for(
                sycl::nd_range<3>(
                    sycl::range<3>(1, 1, divUp(p->vocab_size, 256)) *
                        sycl::range<3>(1, 1, 256),
                    sycl::range<3>(1, 1, 256)),
                [=](sycl::nd_item<3> item_ct1) {
                    convert_fp16_to_fp32(s_logits_temp_ct0, s_logits_gpu_ct1,
                                         p_vocab_size_ct2);
                });
        });
    }
    q_ct1.memcpy(s->logits, s->logits_temp, p->vocab_size * sizeof(float))
        .wait();
}

// ----------------------------------------------------------------------------
// byte pair encoding (BPE) tokenizer, encodes strings into tokens so we can prompt

int str_lookup(char *str, char **vocab, int vocab_size) {
    // find the first perfect match for str in vocab, return its index or -1 if not found
    for (int i = 0; i < vocab_size; i++) {
        if (strcmp(str, vocab[i]) == 0) {
            return i;
        }
    }
    return -1;
}

void bpe_encode(char *text, char **vocab, float *vocab_scores, int vocab_size, unsigned int max_token_length, int *tokens, int *n_tokens) {

    // a temporary buffer to merge two consecutive tokens
    char* str_buffer = (char*) malloc((max_token_length*2+1) * sizeof(char)); // *2 for concat, +1 for null terminator

    // first encode every individual byte in the input string
    *n_tokens = 0; // the number of tokens
    for (char *c = text; *c != '\0'; c++) {
        sprintf(str_buffer, "%c", *c);
        int id = str_lookup(str_buffer, vocab, vocab_size);
        if (id == -1) { printf("not good\n"); exit(1);}
        tokens[*n_tokens] = id;
        (*n_tokens)++;
    }

    // merge the best consecutive pair each iteration, according the scores in vocab_scores
    while (1) {
        float best_score = -1e10;
        int best_id = -1;
        int best_idx = -1;

        for (int i=0; i < (*n_tokens-1); i++) {
            // check if we can merge the pair (tokens[i], tokens[i+1])
            sprintf(str_buffer, "%s%s", vocab[tokens[i]], vocab[tokens[i+1]]);
            int id = str_lookup(str_buffer, vocab, vocab_size);
            if (id != -1 && vocab_scores[id] > best_score) {
                // this merge pair exists in vocab! record its score and position
                best_score = vocab_scores[id];
                best_id = id;
                best_idx = i;
            }
        }

        if (best_idx == -1) {
            break; // we couldn't find any more pairs to merge, so we're done
        }

        // merge the consecutive pair (best_idx, best_idx+1) into new token best_id
        tokens[best_idx] = best_id;
        // delete token at position best_idx+1, shift the entire sequence back 1
        for (int i = best_idx+1; i < (*n_tokens-1); i++) {
            tokens[i] = tokens[i+1];
        }
        (*n_tokens)--; // token length decreased
    }

    free(str_buffer);
}

// ----------------------------------------------------------------------------
// utilities

long time_in_ms() {
    // return time in milliseconds, for benchmarking the model speed
    struct timespec time;
    timespec_get(&time, TIME_UTC);
    return time.tv_sec * 1000 + time.tv_nsec / 1000000;
}

unsigned long long rng_seed;
unsigned int random_u32() {
    // xorshift rng: https://en.wikipedia.org/wiki/Xorshift#xorshift.2A
    rng_seed ^= rng_seed >> 12;
    rng_seed ^= rng_seed << 25;
    rng_seed ^= rng_seed >> 27;
    return (rng_seed * 0x2545F4914F6CDD1Dull) >> 32;
}
float random_f32() { // random float32 in [0,1)
    return (random_u32() >> 8) / 16777216.0f;
}

int sample(float* probabilities, int n) {
    // sample index from probabilities, they must sum to 1
    float r = random_f32();
    float cdf = 0.0f;
    for (int i = 0; i < n; i++) {
        cdf += probabilities[i];
        if (r < cdf) {
            return i;
        }
    }
    return n - 1; // in case of rounding errors
}

int argmax(float* v, int n) {
    // return argmax of v in elements 0..n
    int max_i = 0;
    float max_p = v[0];
    for (int i = 1; i < n; i++) {
        if (v[i] > max_p) {
            max_i = i;
            max_p = v[i];
        }
    }
    return max_i;
}
// ----------------------------------------------------------------------------

int main(int argc, char *argv[]) {

    // poor man's C argparse
    char *checkpoint = NULL;  // e.g. out/model.bin
    float temperature = 0.9f; // e.g. 1.0, or 0.0
    int steps = 256;          // max number of steps to run for, 0: use seq_len
    char *prompt = NULL;      // prompt string

    // 'checkpoint' is necessary arg
    if (argc < 2) {
        printf("Usage: %s <checkpoint_file> [temperature] [steps] [prompt]\n", argv[0]);
        return 1;
    }
    if (argc >= 2) {
        checkpoint = argv[1];
    }
    if (argc >= 3) {
        // optional temperature. 0.0 = (deterministic) argmax sampling. 1.0 = baseline
        temperature = atof(argv[2]);
    }
    if (argc >= 4) {
        steps = atoi(argv[3]);
    }
    if (argc >= 5) {
        prompt = argv[4];
    }

    // seed rng with time. if you want deterministic behavior use temperature 0.0
    rng_seed = (unsigned int)time(NULL);

    // read in the model.bin file
    Config config;
    TransformerWeights weights;
    int shared_weights;
    {
        FILE *file = fopen(checkpoint, "rb");
        if (!file) { printf("Couldn't open file %s\n", checkpoint); return 1; }
        // read in the config header
        if (fread(&config, sizeof(Config), 1, file) != 1) { return 1; }

        // Dump model config
        printf("\nModel params:- \ndim: %d \nhidden_dim: %d\nn_heads: %d\nn_kv_heads: %d\nn_layers: %d\nseq_len: %d\nvocab_size: %d\n\n",
            config.dim, config.hidden_dim, config.n_heads, config.n_kv_heads, config.n_layers, config.seq_len, config.vocab_size);

        // negative vocab size is hacky way of signaling unshared weights. bit yikes.
        shared_weights = config.vocab_size > 0 ? 1 : 0;
        config.vocab_size = abs(config.vocab_size);
        // read in the Transformer weights
        malloc_weights(&weights, &config, shared_weights);
        if (checkpoint_init_weights(&weights, &config, file, shared_weights)) { return 1; }
    }
    // right now we cannot run for more than config.seq_len steps
    if (steps <= 0 || steps > config.seq_len) { steps = config.seq_len; }

    // read in the tokenizer.bin file
    char** vocab = (char**)malloc(config.vocab_size * sizeof(char*));
    float* vocab_scores = (float*)malloc(config.vocab_size * sizeof(float));
    unsigned int max_token_length;
    {
        FILE *file = fopen("tokenizer.bin", "rb");
        if (!file) { printf("couldn't load tokenizer.bin\n"); return 1; }
        if (fread(&max_token_length, sizeof(int), 1, file) != 1) { printf("failed read\n"); return 1; }
        int len;
        for (int i = 0; i < config.vocab_size; i++) {
            if (fread(vocab_scores + i, sizeof(float), 1, file) != 1) { printf("failed read\n"); return 1;}
            if (fread(&len, sizeof(int), 1, file) != 1) { printf("failed read\n"); return 1; }
            vocab[i] = (char *)malloc(len + 1);
            if (fread(vocab[i], len, 1, file) != 1) { printf("failed read\n"); return 1; }
            vocab[i][len] = '\0'; // add the string terminating token
        }
        fclose(file);
    }

    // create and init the application RunState
    RunState state;
    malloc_run_state(&state, &config);

    // process the prompt, if any
    int *prompt_tokens = NULL;
    int num_prompt_tokens = 0;
    if (prompt != NULL) {
        prompt_tokens = (int*)malloc(config.seq_len * sizeof(int));
        bpe_encode(prompt, vocab, vocab_scores, config.vocab_size, max_token_length, prompt_tokens, &num_prompt_tokens);
    }

    // start the main loop
    long start = 0;  // used to time our code, only initialized after first iteration
    int next;        // will store the next token in the sequence
    int token = 1;   // init with token 1 (=BOS), as done in Llama-2 sentencepiece tokenizer
    int pos = 0;     // position in the sequence
    printf("<s>\n"); // explicit print the initial BOS token for stylistic symmetry reasons
    while (pos < steps) {

        // forward the transformer to get logits for the next token
        transformer(token, pos, &config, &state, &weights);

        if(pos < num_prompt_tokens) {
            // if we are still processing the input prompt, force the next prompt token
            next = prompt_tokens[pos];
        } else {
            // sample the next token
            if (temperature == 0.0f) {
                // greedy argmax sampling: take the token with the highest probability
                next = argmax(state.logits, config.vocab_size);
            } else {
                // apply the temperature to the logits
                for (int q=0; q<config.vocab_size; q++) { state.logits[q] /= temperature; }
                // apply softmax to the logits to get the probabilities for next token
                softmax(state.logits, config.vocab_size);
                // we sample from this distribution to get the next token
                next = sample(state.logits, config.vocab_size);
            }
        }

        // following BOS token (1), sentencepiece decoder strips any leading whitespace (see PR #89)
        char *token_str = (token == 1 && vocab[next][0] == ' ') ? vocab[next]+1 : vocab[next];
        printf("%s", token_str);
        fflush(stdout);

        if (next == 2) break; // break if EOS token is reached

        // advance forward
        token = next;
        pos++;
        // init our timer here because the first iteration could be slow
        if (start == 0) { start = time_in_ms(); }
    }

    // report achieved tok/s
    long end = time_in_ms();
    double time = (end - start) / 1000.0;
    int timed_tokens = pos - 1;
    printf("\nachieved tok/s: %f. Tokens: %d, seconds: %g\n", timed_tokens / time, timed_tokens, time);

    // memory cleanup
    free_run_state(&state);
    free_weights(&weights, shared_weights);
    for (int i = 0; i < config.vocab_size; i++) { free(vocab[i]); }
    free(vocab);
    free(vocab_scores);
    if (prompt_tokens != NULL) free(prompt_tokens);
    return 0;
}

